{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In healthy men, 11C-SCH 23390—the closest high-transfer analogue sharing the 7-chloro-8-hydroxy-N-methyl-benzazepine core—showed rapid transfer into brain (1.2% injected radioactivity at 4.5 min), demonstrating meaningful CNS access despite the same ionizable phenol/amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The 4-[125I]iodophenyl analogue ([125I]FISCH) showed good rat brain uptake (2.27% dose/whole brain at 2 min), showing that para-halogenated aryl substitution on this scaffold preserves BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "The 3-iodophenyl analogue S-(-)-8 had good initial brain uptake in rats (1.59% dose/organ at 2 min) and was explicitly labeled as good penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "[123I]SCH 23982, a closely related benzazepine, gave a brain-to-blood ratio of about 1.2 at 10 min in rats, indicating active brain uptake.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close structural analogue of SCH 23390 and related 1-aryl-3-benzazepines with direct human and rodent evidence of rapid, meaningful brain uptake. Its added brominated dihydrobenzofuran moiety is lipophilic and does not introduce a new polar/ionization liability beyond the shared phenol/tertiary-amine features already present in permeable analogues. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain/plasma or PET measurement for the exact query molecule.",
    "Efflux transporter phenotype (e.g., P-gp) was not directly measured for the query, although close analogues show net brain uptake.",
    "Quantitative human CNS exposure for the brominated dihydrobenzofuran analogue is unavailable."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

